Font F(float size,bool bold=false){string key=size+"/"+bold;if(!fonts.ContainsKey(key))fonts[key]=new Font("Segoe UI",size*1.08f,bold?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Pixel);return fonts[key];}
bool Offscreen(int y,int height){return content&&(y+height<Scroll+88||y>Scroll+ClientSize.Height);}
void TextAt(string text,int x,int y,int width,float size=15,Color? color=null,bool bold=false,int height=28){if(Offscreen(y,Math.Max(height,(int)size+8)))return;using(var b=new SolidBrush(color??white))using(var fmt=new StringFormat{Trimming=StringTrimming.EllipsisCharacter,FormatFlags=StringFormatFlags.LineLimit})g.DrawString(text??"",F(size,bold),b,new RectangleF(x,y,width,Math.Max(height,(int)Math.Ceiling(F(size,bold).GetHeight(g))+4)),fmt);}
