double Hover(string key,Rectangle screen){double value;hoverValues.TryGetValue(key,out value);double target=screen.Contains(pointer)?1:0;value=Preferences.Animations?FrameClock.Approach(value,target,frameDelta):target;hoverValues[key]=value;return value;}
