Image Photo(int index){if(!images.ContainsKey(index)){using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("track"+index)){if(stream!=null)using(var img=Image.FromStream(stream))images[index]=new Bitmap(img);else images[index]=null;}}return images[index];}
readonly Dictionary<string,Bitmap> scaledPhotos=new Dictionary<string,Bitmap>();readonly Dictionary<string,long> scaledPhotoUse=new Dictionary<string,long>();long photoClock,scaledPhotoPixels;
void CachePhoto(string key,Bitmap frame){long pixels=(long)frame.Width*frame.Height;while(scaledPhotos.Count>0&&(scaledPhotos.Count>=64||scaledPhotoPixels+pixels>8000000)){string oldest=scaledPhotoUse.OrderBy(p=>p.Value).First().Key;var old=scaledPhotos[oldest];scaledPhotoPixels-=(long)old.Width*old.Height;scaledPhotos.Remove(oldest);scaledPhotoUse.Remove(oldest);old.Dispose();}scaledPhotos[key]=frame;scaledPhotoUse[key]=++photoClock;scaledPhotoPixels+=pixels;}

void Photograph(int index,Rectangle r){if(Offscreen(r.Y,r.Height))return;if(r.Width<1||r.Height<1)return;var img=Photo(index);if(img==null)return;string key=index+"/"+r.Width+"/"+r.Height;Bitmap frame;if(!scaledPhotos.TryGetValue(key,out frame)){frame=new Bitmap(r.Width,r.Height);double ratio=Math.Max(r.Width/(double)img.Width,r.Height/(double)img.Height);var source=new RectangleF((float)((img.Width-r.Width/ratio)/2),(float)((img.Height-r.Height/ratio)/2),(float)(r.Width/ratio),(float)(r.Height/ratio));using(var canvas=Graphics.FromImage(frame))canvas.DrawImage(img,new Rectangle(Point.Empty,r.Size),source,GraphicsUnit.Pixel);CachePhoto(key,frame);}scaledPhotoUse[key]=++photoClock;g.DrawImageUnscaled(frame,r.Location);}

void DriverPortrait(Person p,Rectangle r){if(Offscreen(r.Y,r.Height))return;var img=DriverPhotos.Get(p);Box(r.X,r.Y,r.Width,r.Height,Color.FromArgb(35,35,35));if(img!=null){string key="driver/"+p.Name+"/"+r.Width+"/"+r.Height;Bitmap frame;if(!scaledPhotos.TryGetValue(key,out frame)){frame=new Bitmap(r.Width,r.Height);using(var canvas=Graphics.FromImage(frame))canvas.DrawImage(img,new Rectangle(Point.Empty,r.Size));CachePhoto(key,frame);}scaledPhotoUse[key]=++photoClock;g.DrawImageUnscaled(frame,r.Location);}else TextAt(p.Name.Substring(0,1),r.X+8,r.Y+8,r.Width-10,20,red,true,40);}

