internal void SimulateNext(){if(activeOverlay!=null)return;string problem=Engine.Ready(State);if(problem!="")throw new Exception(problem);Engine.PrepareWeekend(State);bool ongoing=State.Weekend.Live!=null&&!State.Weekend.Live.Finished;string name=ongoing?State.Weekend.Live.Name:Engine.Sessions(State)[State.Stage];if(!ongoing&&(name=="Гонка"||name=="Спринт")){var selector=new StrategyOverlay(State,Preferences.Animations);selector.CancelRequested+=()=>CloseOverlay(null);selector.Confirmed+=()=>CloseOverlay(()=>BeginSimulation(name));ShowOverlay(selector);}else BeginSimulation(name);}
void BeginSimulation(string name){if(name=="Гонка"||name=="Спринт"){BeginLiveRace(name);return;}int completedRound=State.Round,completedYear=State.Year;var snapshot=Engine.Deserialize(Engine.Serialize(State));var simulation=new SimulationOverlay(snapshot,name,Preferences.Animations);simulation.Completed+=(result,error)=>CloseOverlay(()=>{if(error!=null){Notify("Симуляция не завершена: "+error.Message);return;}State=result;View="game";Page="race";Scroll=0;scrollTarget=0;SaveSilent();StartTransition();PresentSession(name,completedRound,completedYear);});ShowOverlay(simulation);}
