Box(X,y,W,250);TextAt("Как работает симуляция",X+20,y+16,W-40,23,white,true,35);TextAt("Практики, сегменты квалификации, спринт и гонка рассчитываются целиком. Нажмите «Симулировать»: короткая красно-бело-чёрная анимация всегда появляется перед результатами. Игровые круги и дистанции сохранены; ждать их в реальном времени не нужно.\n\nПеред спринтом и Гран-при открывается отдельное окно: выберите стратегию, круги остановок и шины для каждого пилота. Можно редактировать рекомендованный план. При изменении погоды инженер автоматически меняет состав шин.\n\nТемп зависит от пилота, болида, инженера, сработанности, шин и повреждений. Сходы, Safety Car, очки и архив продолжают рассчитываться.",X+20,y+60,W-40,14,muted,false,177);y+=275;
Box(X,y,W,195);TextAt("Долгая карьера и финансы",X+20,y+15,W-40,23,white,true,35);TextAt("Годовой лимит разработки — $95 млн. Слоты и инженеры заняты до поставки детали. При провале испытаний проект закрывается без прироста; затраты не возвращаются.\n\nЗарплаты и мотор оплачиваются частями на этапах. Доход: спонсоры, очки и сезонные призовые. Договоры на будущий сезон активируются автоматически. Пилоты объявляют об уходе в начале последнего сезона в возрасте 36–48 лет. Новые вымышленные специалисты и пилоты появляются ежегодно.",X+20,y+59,W-40,14,muted,false,122);y+=220;
Box(X,y,W,175);TextAt("Об игре и исходных данных",X+20,y+15,W-40,23,white,true,35);TextAt("Нативная фанатская игра для личного использования; не связана с Formula One, FIA и командами. Реальные фотографии трасс встроены в EXE; авторы и лицензии — photo-credits.json. Источники и сопоставление должностей перечислены в SOURCES.md. Реальные имена; игровые зарплаты, рейтинги и сроки договоров. * — вымышленные люди. Снимок персонала 2026, не онлайн-обновления.\n\nСимуляция управленческая: нет 3D, полного свода штрафов FIA и точной геометрии обгонов. Карьера первой браузерной версии имеет другую схему и не импортируется как версия 2.",X+20,y+59,W-40,13,muted,false,108);y+=200;
TextAt("Последние финансовые операции",X,y,W,22,white,true);y+=43;foreach(var item in State.Ledger.Take(35)){Box(X,y,W,44);TextAt(item.Year+"  /  "+item.Text,X+14,y+11,W-195,13,muted);TextAt(Engine.Money(item.Value),X+W-175,y+10,160,15,item.Value>=0?Color.LightGreen:red,true);y+=48;}return y+30;}
void PhotoDialog(int index){using(var d=new Form{Text=Data.Tracks[index].Name+" / фотография трассы",Size=new Size(1100,750),StartPosition=FormStartPosition.CenterParent,BackColor=bg}){var pic=new PictureBox{Dock=DockStyle.Fill,Image=Photo(index),SizeMode=PictureBoxSizeMode.Zoom};d.Controls.Add(pic);ShowModal(d);}}

void EngineDialog(){var s=State;using(var d=new DialogForm("Поставщик двигателя",600,470)){d.Info("Заводские команды не меняют двигатель. Клиентский договор в межсезонье действует сразу, в течение сезона — со следующего года.",75);var supplier=d.Combo("Производитель",Data.Engines,0);var term=d.Number("Срок, сезонов",3,2,4,0);var info=d.Info("",90);Action update=()=>info.Text="Мощность: "+Data.EnginePower[supplier.SelectedIndex]+" / надёжность: "+Data.EngineReliability[supplier.SelectedIndex]+"\nГодовая цена: "+Engine.Money(Data.EnginePrice[supplier.SelectedIndex])+". Подписание: $3 млн.\nПри немедленной смене действующего двигателя: отступные 25% годовой цены.";supplier.SelectedIndexChanged+=(o,e)=>update();update();d.Accept("Заключить договор",()=>{Engine.EngineDeal(s,supplier.Text,(int)term.Value);d.DialogResult=DialogResult.OK;});ShowModal(d);}}
void ArchiveDialog(){using(var d=new DialogForm("Выбрать этап",650,250)){var box=d.Combo("Сезон и Гран-при",State.Archive.Select(h=>h.Year+" / "+Data.Tracks[h.Round].Country).ToArray(),archiveIndex);d.Accept("Открыть",()=>{archiveIndex=box.SelectedIndex;archiveSession="Гонка";d.DialogResult=DialogResult.OK;});ShowModal(d);}}
void Export(){using(var d=new SaveFileDialog{Title="Экспорт карьеры",Filter="Карьера F1 Manager|*.json",FileName="F1-Manager-"+State.Year+".json",InitialDirectory=Root})if(ShowModal(d)==DialogResult.OK){Engine.Save(State,d.FileName);Notify("Карьера экспортирована в "+d.FileName);}}
void Import(){using(var d=new OpenFileDialog{Title="Импорт карьеры версии 2–7",Filter="Карьера F1 Manager|*.json;*.bak",InitialDirectory=Root})if(ShowModal(d)==DialogResult.OK){var info=new FileInfo(d.FileName);if(info.Length>100000000)throw new Exception("Файл слишком большой.");var candidate=Engine.Deserialize(File.ReadAllText(d.FileName));if(State!=null&&MessageBox.Show(this,"Заменить текущую карьеру на "+candidate.Year+" / "+Engine.Team(candidate,candidate.Player).Name+"?","Импорт",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;State=candidate;if(State.Weekend!=null&&State.Weekend.Live!=null)State.Weekend.Live.Paused=true;Go("home");SaveSilent();}}
public new void Capture(string page,string path){View="game";Page=page;Scroll=0;scrollTarget=0;transitionStart=-100;Invalidate();Update();using(var bmp=new Bitmap(ClientSize.Width,ClientSize.Height)){DrawToBitmap(bmp,new Rectangle(Point.Empty,ClientSize));bmp.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}
}
public class DialogForm:Form {Panel panel=new Panel();FlowLayoutPanel flow=new FlowLayoutPanel();public DialogForm(string title,int width,int height){Text=title;Size=new Size(width,height);MinimumSize=new Size(width,Math.Min(500,height));StartPosition=FormStartPosition.CenterParent;BackColor=Color.FromArgb(21,21,21);ForeColor=Color.White;Font=new Font("Segoe UI",10);AutoScaleMode=AutoScaleMode.None;panel.Dock=DockStyle.Fill;panel.AutoScroll=true;Controls.Add(panel);flow.FlowDirection=FlowDirection.TopDown;flow.WrapContents=false;flow.AutoSize=true;flow.AutoSizeMode=AutoSizeMode.GrowAndShrink;flow.Padding=new Padding(24,15,20,25);flow.Width=width-35;panel.Controls.Add(flow);}
public void Portrait(string name,Image image){var row=new Panel{Width=ClientSize.Width-76,Height=82,Margin=new Padding(0,12,0,8),BackColor=Color.FromArgb(30,30,30)};var pic=new PictureBox{Image=image,SizeMode=PictureBoxSizeMode.Zoom,Location=new Point(8,4),Size=new Size(64,74)};row.Controls.Add(pic);row.Controls.Add(new Label{Text=name,Location=new Point(88,25),Width=row.Width-100,Height=35,ForeColor=Color.White,Font=new Font("Segoe UI",14,FontStyle.Bold)});flow.Controls.Add(row);}
public Label Info(string s,int height=48){var l=new Label{Text=s,Width=ClientSize.Width-72,Height=height,ForeColor=Color.FromArgb(182,182,182),Margin=new Padding(0,0,0,10),AutoSize=false};flow.Controls.Add(l);return l;}
void Label(string s){flow.Controls.Add(new Label{Text=s,Width=ClientSize.Width-72,Height=23,Margin=new Padding(0,7,0,0)});}
public TextBox Input(string title,string value){Label(title);var x=new TextBox{Text=value,Width=ClientSize.Width-76,BackColor=Color.FromArgb(34,34,34),ForeColor=Color.White,BorderStyle=BorderStyle.FixedSingle,Margin=new Padding(0,0,0,7)};flow.Controls.Add(x);return x;}
public ComboBox Combo(string title,string[] options,int selected){Label(title);var x=new ComboBox{Width=ClientSize.Width-76,BackColor=Color.FromArgb(34,34,34),ForeColor=Color.White,DropDownStyle=ComboBoxStyle.DropDownList,FlatStyle=FlatStyle.Flat,Margin=new Padding(0,0,0,7)};x.Items.AddRange(options);if(options.Length>0)x.SelectedIndex=Math.Min(options.Length-1,Math.Max(0,selected));flow.Controls.Add(x);return x;}
public SliderInput Number(string title,decimal value,decimal min,decimal max,int digits){var x=new SliderInput{Width=ClientSize.Width-76,DecimalPlaces=digits,Increment=digits==0?1:.1m,Caption=title,Margin=new Padding(0,0,0,7)};x.SetRange(min,max);x.Value=value;flow.Controls.Add(x);return x;}
public void Accept(string title,Action action){var error=Info("",0);error.ForeColor=Color.FromArgb(255,111,117);var btn=new Button{Text=title,Width=ClientSize.Width-76,Height=42,FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(218,17,30),ForeColor=Color.White,Margin=new Padding(0,12,0,4)};btn.FlatAppearance.BorderSize=0;btn.Click+=(o,e)=>{try{action();}catch(Exception ex){error.Height=65;error.Text=ex.Message;panel.ScrollControlIntoView(error);}};flow.Controls.Add(btn);AcceptButton=btn;}
}
}
